{"cards": [{"node_code": "N_b74ad1f3c0370118", "definition": "记录机械工程领域标准化体系、质量控制及安全规范从建立到演变的关键历史节点，涵盖重要标准颁布、制度确立及其对行业的影响。", "boundary": "本节点聚焦于“制度与规范”层面的历史事件，如ISO/ASTM等标准体系的创立、关键质量/安全法规的出台。边界在于内容必须体现标准或制度的“历史性确立或变革”，而非现行标准的具体技术参数或操作细节。若侧重标准背后的技术原理，归入技术分支；若侧重制定标准的人物，归入人物节点。", "includes": ["国际/国家机械工程标准体系（如ISO、ASTM、GB）的成立与关键版本发布事件", "质量管理体系（如ISO 9000系列）及安全规范在机械行业的引入与确立历史", "计量单位、公差配合等基础工程规范的标准化进程及里程碑事件"], "excludes": ["现行有效的标准文本、具体技术参数表或操作手册（无历史语境）", "具体机械装备的结构发明或制造工艺突破（应归入动力或制造节点）", "标准制定者的个人生平传记（应归入人物节点）"], "sibling_distinctions": [{"other_code": "N_056e79960356a6ab", "rule": "本节点收录标准、规范及制度的确立事件；兄弟节点收录学会、研究机构及教育体系的成立与变革事件。"}, {"other_code": "N_2a2ee69e6f9a230e", "rule": "本节点收录规范性制度（如标准颁布）的历史；兄弟节点收录具体工程项目实施或事故发生的实例历史。"}], "cross_boundary_rule": "若内容核心是“某项标准/制度何时确立及其历史意义”，归入本节点；若核心是“某机构何时成立”，归入学会/机构节点；若核心是“某工程事故如何发生”，归入工程/事故节点。"}, {"node_code": "N_056e79960356a6ab", "definition": "记录机械工程领域重要学术组织、研究机构及教育体系的建立、合并、改革等历史性事件，反映学科组织形态的演变。", "boundary": "本节点聚焦于“组织与机构”层面的历史节点，如学会成立、实验室建立、课程改革等。边界在于内容必须体现机构或教育体系的“历史性建立或重大变革”，而非机构当前的职能介绍或具体研究成果。若侧重机构中某位人物的贡献，归入人物节点；若侧重机构发布的标准，归入标准节点。", "includes": ["重要机械工程学会（如ASME、IMechE）的成立、合并及重大改革事件", "关键机械研究机构、实验室或大学的建立、更名及学科调整历史", "机械工程教育体系、学位制度及专业设置的演变与确立事件"], "excludes": ["机构当前发布的最新研究报告、技术论文或项目成果（无历史事件属性）", "具体机械装备的发明或制造工艺突破（应归入动力或制造节点）", "机构中具体人物的详细生平传记（应归入人物节点）"], "sibling_distinctions": [{"other_code": "N_b74ad1f3c0370118", "rule": "本节点收录学会、研究机构及教育体系的成立与变革事件；兄弟节点收录标准、规范及制度的确立事件。"}, {"other_code": "N_2a2ee69e6f9a230e", "rule": "本节点收录组织/教育机构的沿革历史；兄弟节点收录具体工程项目实施或事故发生的实例历史。"}], "cross_boundary_rule": "若内容核心是“某机构/教育体系何时成立或变革”，归入本节点；若核心是“某项标准何时颁布”，归入标准节点；若核心是“某工程事故如何发生”，归入工程/事故节点。"}, {"node_code": "N_2a2ee69e6f9a230e", "definition": "记录具有历史意义的重大机械工程项目实施过程及重大事故教训，涵盖大型设施建设、工程失败案例及其对行业的影响。", "boundary": "本节点聚焦于“具体工程实践与事故”层面的历史事件，如大型桥梁/工厂建设、重大机械故障/事故。边界在于内容必须体现具体工程项目的“实施过程”或“事故教训”，而非通用的工程理论或标准规范。若侧重工程中的具体机械发明，归入动力/制造节点；若侧重事故引发的标准变革，可关联标准节点但主挂载在此。", "includes": ["具有历史标志性的大型机械工程项目（如大型水坝、工厂、桥梁）的建设历程与里程碑", "重大机械事故（如结构失效、设备爆炸）的发生过程、原因分析及行业教训", "工程实践中的关键决策、技术挑战及解决方案的历史记录"], "excludes": ["通用机械设计理论、材料力学原理或制造工艺方法（无具体工程/事故语境）", "现行有效的工程操作规范、安全手册或标准文本（无历史事件属性）", "具体机械装备的结构发明或技术突破（应归入动力或制造节点）"], "sibling_distinctions": [{"other_code": "N_b74ad1f3c0370118", "rule": "本节点收录具体工程项目实施或事故发生的实例历史；兄弟节点收录规范性制度（如标准颁布）的历史。"}, {"other_code": "N_056e79960356a6ab", "rule": "本节点收录具体工程项目实施或事故发生的实例历史；兄弟节点收录组织/教育机构的沿革历史。"}], "cross_boundary_rule": "若内容核心是“某具体工程/事故如何发生及其教训”，归入本节点；若核心是“某项标准/制度何时确立”，归入标准节点；若核心是“某机构何时成立”，归入学会/机构节点。"}]}
